#include <iostream>
#include <vector>
using namespace std;

typedef vector<vector<int>> Matrix;

// Naive O(n^3) matrix multiplication for comparison
Matrix naiveMultiply(Matrix& A, Matrix& B) {
    int n = A.size();
    Matrix C(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            for (int k = 0; k < n; k++)
                C[i][j] += A[i][k] * B[k][j];
    return C;
}

// Helper functions for Strassen's
Matrix add(Matrix& A, Matrix& B) {
    int n = A.size();
    Matrix C(n, vector<int>(n));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            C[i][j] = A[i][j] + B[i][j];
    return C;
}

Matrix sub(Matrix& A, Matrix& B) {
    int n = A.size();
    Matrix C(n, vector<int>(n));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            C[i][j] = A[i][j] - B[i][j];
    return C;
}

Matrix strassen(Matrix& A, Matrix& B) {
    int n = A.size();
    if (n == 1) {
        return {{A[0][0] * B[0][0]}};
    }

    int half = n / 2;
    // Split into sub-matrices
    Matrix A11(half, vector<int>(half)), A12(half, vector<int>(half));
    Matrix A21(half, vector<int>(half)), A22(half, vector<int>(half));
    Matrix B11(half, vector<int>(half)), B12(half, vector<int>(half));
    Matrix B21(half, vector<int>(half)), B22(half, vector<int>(half));

    for (int i = 0; i < half; i++)
        for (int j = 0; j < half; j++) {
            A11[i][j] = A[i][j];           A12[i][j] = A[i][j+half];
            A21[i][j] = A[i+half][j];      A22[i][j] = A[i+half][j+half];
            B11[i][j] = B[i][j];           B12[i][j] = B[i][j+half];
            B21[i][j] = B[i+half][j];      B22[i][j] = B[i+half][j+half];
        }

    // 7 multiplications (instead of 8)
    auto t1 = sub(B12, B22); auto P1 = strassen(A11, t1);
    auto t2 = add(A11, A12); auto P2 = strassen(t2, B22);
    auto t3 = add(A21, A22); auto P3 = strassen(t3, B11);
    auto t4 = sub(B21, B11); auto P4 = strassen(A22, t4);
    auto t5a = add(A11, A22); auto t5b = add(B11, B22); auto P5 = strassen(t5a, t5b);
    auto t6a = sub(A12, A22); auto t6b = add(B21, B22); auto P6 = strassen(t6a, t6b);
    auto t7a = sub(A11, A21); auto t7b = add(B11, B12); auto P7 = strassen(t7a, t7b);

    // Combine results
    // C11 = P5 + P4 - P2 + P6
    // C12 = P1 + P2
    // C21 = P3 + P4
    // C22 = P5 + P1 - P3 - P7
    auto c1 = add(P5, P4); auto c2 = sub(c1, P2); auto C11 = add(c2, P6);
    auto C12 = add(P1, P2);
    auto C21 = add(P3, P4);
    auto c3 = add(P5, P1); auto c4 = sub(c3, P3); auto C22 = sub(c4, P7);

    Matrix C(n, vector<int>(n));
    for (int i = 0; i < half; i++)
        for (int j = 0; j < half; j++) {
            C[i][j] = C11[i][j];           C[i][j+half] = C12[i][j];
            C[i+half][j] = C21[i][j];      C[i+half][j+half] = C22[i][j];
        }
    return C;
}

int main() {
    Matrix A = {{1, 2}, {3, 4}};
    Matrix B = {{5, 6}, {7, 8}};
    Matrix C = strassen(A, B);

    cout << "Result:" << endl;
    for (auto& row : C) {
        for (int x : row) cout << x << " ";
        cout << endl;
    }
    // Output: 19 22 / 43 50
    return 0;
}

