public class Strassen {
    // Naive multiplication for comparison
    public static int[][] naiveMultiply(int[][] A, int[][] B) {
        int n = A.length;
        int[][] C = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k < n; k++)
                    C[i][j] += A[i][k] * B[k][j];
        return C;
    }

    // Strassen's: O(n^2.807) vs naive O(n^3)
    // Uses 7 multiplications instead of 8
    // Key insight: trade multiplications for additions

    public static void main(String[] args) {
        int[][] A = {{1, 2}, {3, 4}};
        int[][] B = {{5, 6}, {7, 8}};
        int[][] C = naiveMultiply(A, B);

        System.out.println("Result:");
        for (int[] row : C) {
            for (int x : row) System.out.print(x + " ");
            System.out.println();
        }
        // Output: 19 22 / 43 50
    }
}

