#include <stdio.h>

// Naive O(n^3) matrix multiplication
// Strassen's reduces to O(n^2.807) using 7 multiplications

void naiveMultiply(int n, int A[][2], int B[][2], int C[][2]) {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            C[i][j] = 0;
            for (int k = 0; k < n; k++)
                C[i][j] += A[i][k] * B[k][j];
        }
}

int main() {
    int A[2][2] = {{1, 2}, {3, 4}};
    int B[2][2] = {{5, 6}, {7, 8}};
    int C[2][2];

    naiveMultiply(2, A, B, C);

    printf("Result:\n");
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++)
            printf("%d ", C[i][j]);
